    90		Base       string            `json:"base"`
    91		Head       string            `json:"head"`
    92		Files      []FileChange      `json:"files"`
    93		Warnings   []ProviderWarning `json:"warnings,omitempty"`
    94		// SchemaVersion pins the shape of this Result so a copy persisted into
