    71		AfterStartLine  int     `json:"after_start_line,omitempty"`
    72		DependentsCount int     `json:"dependents_count"`
    73		Similarity      float64 `json:"similarity,omitempty"`
    74		// Reconciliation carries explicit identity-continuity metadata when a
    75		// delete+add pair was reconciled to a single change: RENAMED (same file),
    76		// MOVED (across files), or RECONCILED_FROM. Empty for ordinary changes.
    77		Reconciliation string `json:"reconciliation,omitempty"`
