    97		// single place Result is constructed with real content
    98		// (AnalyzeGitRangeWithOptions) — every caller (diff, analyze, checkpoint)
    99		// funnels through it.
   100		SchemaVersion string `json:"schema_version"`
   101		// ProducerVersion is the entire-graph binary version that produced this
