+	if errors.Is(err, coordinate.ErrTeamNotFound) || errors.Is(err, coordinate.ErrAgentNotFound) {
+		status = http.StatusNotFound
+	}
+	writeAPIJSON(out, status, map[string]string{"error": err.Error()})
+}
