    quotedAt: input.quotedAt.toISOString(),
    expiresAt: new Date(input.quotedAt.getTime() + input.ttlSeconds * 1_000).toISOString(),
    executable: false as const,
  };

  return { ...unsigned, canonicalHash: canonicalHash(unsigned) };
}

