import { useState } from 'react';
import type { CoordinatePlan, PublicSession } from '../api';
import type { DashboardSnapshot } from '../domain';
import { Dashboard } from './Dashboard';

type View = 'team' | 'plan' | 'tracker' | 'activity';

export function Workflow({ snapshot, plan, sessions, onSave }: { snapshot: DashboardSnapshot; plan: CoordinatePlan; sessions: PublicSession[]; onSave: (plan: CoordinatePlan) => Promise<void> }) {
  const [view, setView] = useState<View>('tracker');
  const [draft, setDraft] = useState(plan);
  const [saving, setSaving] = useState(false);
  const save = async () => { setSaving(true); try { await onSave(draft); } finally { setSaving(false); } };
  const addMember = () => setDraft({ ...draft, team: { ...draft.team, members: [...draft.team.members, { id: `member-${crypto.randomUUID()}`, name: 'New teammate', session_ids: [] }] } });
  const addMission = () => setDraft({ ...draft, missions: [...draft.missions, { id: `mission-${crypto.randomUUID()}`, title: 'New task', owner: draft.team.members[0]?.id ?? '', status: 'queued', targets: [{ file: 'README.md' }] }] });

  return <div className="workflow-shell">
    <nav className="workflow-nav" aria-label="Product workflow">
      {(['team', 'plan', 'tracker', 'activity'] as View[]).map((item) => <button className={view === item ? 'active' : ''} onClick={() => setView(item)} key={item}>{item === 'team' ? '1. Team setup' : item === 'plan' ? '2. Plan & assign' : item === 'tracker' ? '3. Spidey tracker' : 'Agent activity'}</button>)}
    </nav>
    {view === 'tracker' ? <Dashboard snapshot={snapshot} /> : null}
    {view === 'team' ? <main className="focused-page"><header><p className="eyebrow">Step one</p><h1>Create your team</h1><p>Add any number of teammates, then map each person to a detected Entire agent session.</p></header><div className="editor-list">{draft.team.members.map((member, index) => <article key={member.id}><input aria-label="Member name" value={member.name} onChange={(event) => { const members = [...draft.team.members]; members[index] = { ...member, name: event.target.value }; setDraft({ ...draft, team: { ...draft.team, members } }); }} /><select aria-label={`Agent session for ${member.name}`} value={member.session_ids?.[0] ?? ''} onChange={(event) => { const members = [...draft.team.members]; members[index] = { ...member, session_ids: event.target.value ? [event.target.value] : [] }; setDraft({ ...draft, team: { ...draft.team, members } }); }}><option value="">Not connected</option>{sessions.map((session) => <option value={session.session_id} key={session.session_id}>{session.agent} · {session.status} · {session.session_id.slice(0, 8)}</option>)}</select></article>)}</div><div className="editor-actions"><button onClick={addMember}>Add teammate</button><button className="primary-action" disabled={saving} onClick={save}>Save team</button></div></main> : null}
    {view === 'plan' ? <main className="focused-page"><header><p className="eyebrow">Step two</p><h1>Plan and assign</h1><p>The leader assigns tasks and declares the files or symbols each task expects to change.</p></header><div className="editor-list">{draft.missions.map((mission, index) => <article key={mission.id}><input aria-label="Task title" value={mission.title} onChange={(event) => { const missions = [...draft.missions]; missions[index] = { ...mission, title: event.target.value }; setDraft({ ...draft, missions }); }} /><select aria-label={`Owner for ${mission.title}`} value={mission.owner} onChange={(event) => { const missions = [...draft.missions]; missions[index] = { ...mission, owner: event.target.value }; setDraft({ ...draft, missions }); }}>{draft.team.members.map((member) => <option value={member.id} key={member.id}>{member.name}</option>)}</select><input aria-label="Target file" value={mission.targets[0]?.file ?? ''} onChange={(event) => { const missions = [...draft.missions]; missions[index] = { ...mission, targets: [{ ...mission.targets[0], file: event.target.value }] }; setDraft({ ...draft, missions }); }} /></article>)}</div><div className="editor-actions"><button disabled={!draft.team.members.length} onClick={addMission}>Add task</button><button className="primary-action" disabled={saving} onClick={save}>Save plan</button></div></main> : null}
    {view === 'activity' ? <main className="focused-page"><header><p className="eyebrow">Separate signal view</p><h1>Agent activity</h1><p>Process monitoring stays here so the coordination graph remains clean.</p></header><div className="editor-list">{sessions.map((session) => <article key={session.session_id}><strong>{session.agent}</strong><span>{session.status}</span><code>{session.session_id}</code><small>{session.worktree}</small></article>)}</div></main> : null}
  </div>;
}
import { useMemo, useState } from 'react';
import type { DashboardSnapshot, RiskLevel } from '../domain';
import { EvidencePath } from './EvidencePath';
import { MissionPathways } from './MissionPathways';
import { RiskConsole } from './RiskConsole';
import { GitPanel, GraphPanel, ProviderPanel } from './SystemPanels';
import { TeamLobby } from './TeamLobby';

interface DashboardProps {
  snapshot?: DashboardSnapshot;
  loading?: boolean;
  error?: string;
}

const riskPriority: Record<RiskLevel, number> = { BLOCK: 0, REVIEW: 1, CLEAR: 2 };

export function Dashboard({ snapshot, loading = false, error }: DashboardProps) {
  const orderedRisks = useMemo(
    () => [...(snapshot?.risks ?? [])].sort((left, right) => riskPriority[left.level] - riskPriority[right.level]),
    [snapshot?.risks],
  );
  const [selectedRiskId, setSelectedRiskId] = useState<string | undefined>();
  const selectedRisk = orderedRisks.find((risk) => risk.id === selectedRiskId) ?? orderedRisks[0];

  if (loading) {
    return (
      <main className="state-shell" aria-busy="true" aria-live="polite">
        <div className="loading-radar" aria-hidden="true"><span /></div>
        <p className="eyebrow">Calibrating signal network</p>
        <h1>Mapping the mission web…</h1>
        <p>Resolving sessions, Git activity, and bounded Graph relationships.</p>
      </main>
    );
  }

  if (error || !snapshot) {
    return (
      <main className="state-shell error-shell" role="alert">
        <span className="error-signal" aria-hidden="true">!</span>
        <p className="eyebrow">Provider signal lost</p>
        <h1>Mission control is temporarily offline</h1>
        <p>{error ?? 'No dashboard snapshot is available.'}</p>
        <p className="state-detail">The interface remains stable while providers recover.</p>
      </main>
    );
  }

  const activeMissions = snapshot.missions.filter((mission) => mission.status === 'active').length;
  const blockedMissions = snapshot.missions.filter((mission) => mission.status === 'blocked').length;
  const liveRunners = snapshot.runners.filter((runner) => runner.status === 'active').length;
  const providerOnline = snapshot.providers.filter((provider) => provider.status === 'online').length;

  return (
    <div className="app-shell">
      <header className="topbar">
        <a className="brand" href="#mission-control" aria-label="Spidey Sense mission control home">
          <span className="brand-mark" aria-hidden="true"><i /><i /><i /></span>
          <span><strong>spidey sense</strong><small>graph intelligence</small></span>
        </a>
        <div className="topbar-status">
          <span className="live-dot" aria-hidden="true" />
          <span>{providerOnline}/{snapshot.providers.length} providers online</span>
          <span className="timestamp">Updated {new Date(snapshot.generatedAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
        </div>
      </header>

      <main id="mission-control">
        <section className="hero" aria-labelledby="dashboard-title">
          <div className="hero-web" aria-hidden="true"><span /><span /><span /></div>
          <div className="hero-copy">
            <p className="eyebrow">{snapshot.team.callSign} · Live coordination</p>
            <h1 id="dashboard-title">Sense the collision<br /><em>before it lands.</em></h1>
            <p>{snapshot.team.objective}</p>
          </div>
          <div className="web-emblem" aria-hidden="true">
            <svg viewBox="0 0 320 420" fill="none" xmlns="http://www.w3.org/2000/svg">
              <g className="web-lines">
                <path d="M160 22V398M37 200H283M71 69L249 331M249 69L71 331" />
                <path d="M160 22C157 70 130 93 91 70C118 100 108 143 64 160C111 158 130 179 124 215C116 250 94 286 71 331C112 301 143 313 160 352C177 313 208 301 249 331C226 286 204 250 196 215C190 179 209 158 256 160C212 143 202 100 229 70C190 93 163 70 160 22Z" />
                <path d="M160 79C158 111 141 126 116 111C134 131 130 157 102 168C132 168 144 181 140 204C136 226 122 249 108 277C134 258 150 266 160 291C170 266 186 258 212 277C198 249 184 226 180 204C176 181 188 168 218 168C190 157 186 131 204 111C179 126 162 111 160 79Z" />
              </g>
              <circle className="web-node" cx="160" cy="200" r="5" />
            </svg>
            <span>signal network</span>
          </div>
        </section>

        <section className="summary-grid" aria-label="Mission control summary">
          <article><span>Live runners</span><strong>{liveRunners.toString().padStart(2, '0')}</strong><small>of {snapshot.runners.length} connected</small></article>
          <article><span>Active missions</span><strong>{activeMissions.toString().padStart(2, '0')}</strong><small>{snapshot.missions.length} total pathways</small></article>
          <article className={blockedMissions ? 'alert-metric' : ''}><span>Blocked</span><strong>{blockedMissions.toString().padStart(2, '0')}</strong><small>need coordination</small></article>
          <article><span>Graph relations</span><strong>{snapshot.graph.relationCount.toLocaleString()}</strong><small>depth {snapshot.graph.analyzedDepth} analysis</small></article>
        </section>

        <div className="dashboard-grid">
          <div className="primary-column">
            <TeamLobby team={snapshot.team} runners={snapshot.runners} missions={snapshot.missions} />
            <MissionPathways missions={snapshot.missions} runners={snapshot.runners} />
          </div>
          <aside className="insight-column" aria-label="Coordination intelligence">
            <RiskConsole risks={orderedRisks} selectedRiskId={selectedRisk?.id} onSelectRisk={setSelectedRiskId} />
            <EvidencePath risk={selectedRisk} />
            <ProviderPanel providers={snapshot.providers} />
            <GitPanel git={snapshot.git} />
            <GraphPanel graph={snapshot.graph} />
          </aside>
        </div>
      </main>

      <footer>
        <span>Local-first coordination</span>
        <span>Evidence, not oracle · CLEAR is bounded, not guaranteed</span>
      </footer>
    </div>
  );
}
import type { Mission, Runner, Team } from '../domain';
import { StatusPill } from './StatusPill';

interface TeamLobbyProps {
  team: Team;
  runners: Runner[];
  missions: Mission[];
}

export function TeamLobby({ team, runners, missions }: TeamLobbyProps) {
  const missionById = new Map(missions.map((mission) => [mission.id, mission]));

  return (
    <section className="panel team-panel" aria-labelledby="team-lobby-title">
      <div className="section-heading">
        <div>
          <p className="eyebrow">Team lobby · {team.callSign}</p>
          <h2 id="team-lobby-title">Runners on the web</h2>
        </div>
        <span className="count-badge">{runners.length}</span>
      </div>

      {runners.length === 0 ? (
        <div className="empty-state compact-empty">
          <span className="empty-glyph" aria-hidden="true">○</span>
          <h3>No runners connected</h3>
          <p>Connect an Entire-enabled session to populate the team lobby.</p>
        </div>
      ) : (
        <div className="runner-grid">
          {runners.map((runner) => {
            const mission = runner.currentMissionId ? missionById.get(runner.currentMissionId) : undefined;
            return (
              <article className="runner-card" key={runner.id} style={{ '--runner-accent': runner.accent } as React.CSSProperties}>
                <div className="runner-identity">
                  <span className="runner-avatar" aria-hidden="true">{runner.initials}</span>
                  <div>
                    <h3>{runner.displayName}</h3>
                    <p>{runner.archetype}</p>
                  </div>
                  <StatusPill status={runner.status} />
                </div>
                <p className="runner-role">{runner.role}</p>
                <div className="runner-meta">
                  <span>{runner.provider}</span>
                  <span>{mission?.title ?? 'Awaiting assignment'}</span>
                </div>
              </article>
            );
          })}
        </div>
      )}
    </section>
  );
}
import type { Mission, MissionStatus, Runner } from '../domain';
import { StatusPill } from './StatusPill';

const stages: MissionStatus[] = ['queued', 'active', 'blocked', 'complete'];
const stageLabels: Record<MissionStatus, string> = {
  queued: 'Queued',
  active: 'Active',
  blocked: 'Blocked',
  complete: 'Complete',
};

interface MissionPathwaysProps {
  missions: Mission[];
  runners: Runner[];
}

export function MissionPathways({ missions, runners }: MissionPathwaysProps) {
  const runnerById = new Map(runners.map((runner) => [runner.id, runner]));

  return (
    <section className="panel mission-panel" aria-labelledby="mission-pathways-title">
      <div className="section-heading">
        <div>
          <p className="eyebrow">Dynamic mission pathway</p>
          <h2 id="mission-pathways-title">Work in motion</h2>
        </div>
        <span className="count-badge">{missions.length}</span>
      </div>

      {missions.length === 0 ? (
        <div className="empty-state compact-empty">
          <span className="empty-glyph" aria-hidden="true">◇</span>
          <h3>No missions planned</h3>
          <p>Create a mission to begin coordination analysis.</p>
        </div>
      ) : (
        <div className="mission-list">
          {missions.map((mission) => {
            const owner = mission.ownerId ? runnerById.get(mission.ownerId) : undefined;
            return (
              <article className={`mission-card mission-${mission.status}`} key={mission.id}>
                <div className="mission-copy">
                  <div>
                    <p className="mission-owner">{owner?.displayName ?? 'Unassigned'} · {mission.updatedAt}</p>
                    <h3>{mission.title}</h3>
                    <p>{mission.intent}</p>
                  </div>
                  <StatusPill status={mission.status} />
                </div>

                <ol className="pathway" aria-label={`${mission.title} status: ${stageLabels[mission.status]}`}>
                  {stages.map((stage, index) => {
                    const current = stage === mission.status;
                    const reached = stages.indexOf(mission.status) >= index && mission.status !== 'blocked';
                    return (
                      <li className={current ? 'current' : reached ? 'reached' : ''} key={stage}>
                        <span className="path-dot">{index + 1}</span>
                        <span>{stageLabels[stage]}</span>
                      </li>
                    );
                  })}
                </ol>

                <div className="mission-targets">
                  <span>{mission.targetCount} graph targets</span>
                  <div className="target-chips" aria-label="Mission target files">
                    {mission.targets.map((target) => <code key={target}>{target}</code>)}
                  </div>
                </div>
              </article>
            );
          })}
        </div>
      )}
    </section>
  );
}
:root {
  color-scheme: dark;
  font-family: 'Segoe UI', Helvetica, Arial, sans-serif;
