  --line: rgba(242, 241, 237, 0.13);
  --line-bright: rgba(242, 241, 237, 0.52);
  --muted: #888c89;
  --blue: #7dc3ff;
  --blue-bright: #b9dcfb;
  --red: #ff4b55;
  --green: #8ad8b4;
  --yellow: #e1bf77;
  --violet: #c2aef2;
}

.workflow-nav { position: sticky; top: 0; z-index: 30; display: flex; gap: 0; padding: 0 clamp(1rem, 4vw, 4rem); background: rgba(3,5,4,.94); border-bottom: 1px solid rgba(255,255,255,.12); backdrop-filter: blur(20px); }
.workflow-nav button { position: relative; border: 0; padding: 1.2rem 1.35rem; color: #777c79; background: transparent; cursor: pointer; font-size: .59rem; letter-spacing: .13em; text-transform: uppercase; }
.workflow-nav button::after { content: ''; position: absolute; right: 1.35rem; bottom: -1px; left: 1.35rem; height: 1px; background: transparent; }
.workflow-nav button:hover { color: #c4c7c5; }
.workflow-nav button.active { color: #f2f1ed; background: rgba(255,255,255,.025); }
.workflow-nav button.active::after { background: #f2f1ed; box-shadow: 0 0 12px rgba(255,255,255,.2); }
.focused-page { width: min(980px, calc(100% - 2rem)); margin: 0 auto; padding: clamp(4rem,8vw,7rem) 0; }
.focused-page header { max-width: 680px; margin-bottom: 3.2rem; }
.focused-page h1 { margin: .55rem 0 1rem; font-size: clamp(2.8rem, 6vw, 5.5rem); font-weight: 200; line-height: .95; letter-spacing: -.055em; }
.focused-page header p:last-child { color: #858a87; font-size: .9rem; font-weight: 300; line-height: 1.8; }
.editor-list { display: grid; gap: 1px; background: rgba(255,255,255,.11); }
.editor-list article { display: grid; grid-template-columns: minmax(180px, 1fr) minmax(220px, 1.3fr) minmax(180px, 1fr); gap: .8rem; align-items: center; padding: 1.15rem; background: #080a09; }
.editor-list input, .editor-list select { width: 100%; color: #f2f1ed; background: #0c0f0d; border: 1px solid rgba(255,255,255,.15); border-radius: 0; padding: .85rem; outline: none; }
.editor-list input:focus, .editor-list select:focus { border-color: rgba(255,255,255,.58); box-shadow: 0 0 0 1px rgba(255,255,255,.08); }
.editor-list article > strong { font-weight: 400; }
.editor-list article > span, .editor-list article > small { color: var(--muted); }
.editor-list article > code { color: #aeb3b0; overflow-wrap: anywhere; }
.editor-actions { display: flex; justify-content: space-between; margin-top: 1.2rem; }
.editor-actions button { border: 1px solid rgba(255,255,255,.2); border-radius: 0; padding: .85rem 1.2rem; color: #e6e6e1; background: transparent; cursor: pointer; font-size: .65rem; letter-spacing: .08em; text-transform: uppercase; }
.editor-actions button:hover:not(:disabled) { border-color: rgba(255,255,255,.58); background: rgba(255,255,255,.04); }
.editor-actions button:disabled { cursor: not-allowed; opacity: .38; }
.editor-actions .primary-action { border-color: rgba(255,75,85,.72); color: #fff; background: rgba(255,75,85,.15); }
@media (max-width: 720px) { .workflow-nav { overflow-x: auto; } .workflow-nav button { white-space: nowrap; } .editor-list article { grid-template-columns: 1fr; } }

* { box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  margin: 0;
  min-width: 320px;
  min-height: 100vh;
  background: #030504;
}

body::before {
  content: '';
  position: fixed;
  inset: 0;
  pointer-events: none;
  opacity: 0.36;
  background:
    radial-gradient(circle at 77% 11%, rgba(255,255,255,.045), transparent 22rem),
    linear-gradient(115deg, transparent 0 72%, rgba(255,255,255,.025) 72.1% 72.2%, transparent 72.3%);
}

button, input, textarea, select { font: inherit; }
button { color: inherit; }
a { color: inherit; }

code, .eyebrow, .status-pill, .count-badge, .brand small {
  font-family: 'Cascadia Code', 'SFMono-Regular', Consolas, ui-monospace, monospace;
}

.app-shell { min-height: 100vh; }

.topbar {
  position: sticky;
  z-index: 20;
  top: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 88px;
  padding: 0 4vw;
  border-bottom: 1px solid rgba(255,255,255,.11);
  background: rgba(3, 5, 4, 0.9);
  backdrop-filter: blur(22px);
}

.brand {
  display: flex;
  align-items: center;
  gap: 17px;
  color: #fff;
  font-weight: 300;
  letter-spacing: 0.02em;
  text-decoration: none;
}

.brand > span:last-child { display: flex; flex-direction: column; gap: 2px; }
.brand strong { font-size: 1.15rem; font-weight: 200; letter-spacing: .11em; }
.brand small { color: #7c817e; font-size: 0.5rem; letter-spacing: 0.3em; text-transform: uppercase; }

.brand-mark {
  position: relative;
  display: grid;
  width: 34px;
  aspect-ratio: 1;
  place-items: center;
  border: 0;
  border-radius: 0;
  transform: rotate(45deg);
}

.brand-mark::before, .brand-mark::after, .brand-mark i { content: ''; position: absolute; inset: 2px; border: 1px solid rgba(255,255,255,.72); }
.brand-mark::after { inset: 8px; }
.brand-mark i:nth-child(1) { inset: 14px; background: #f2f1ed; }
.brand-mark i:nth-child(2) { inset: 0 50%; width: 1px; border: 0; background: rgba(255,255,255,.65); }
.brand-mark i:nth-child(3) { inset: 50% 0; height: 1px; border: 0; background: rgba(255,255,255,.65); }

.topbar-status { display: flex; align-items: center; gap: 9px; color: #b8c7dd; font-size: 0.76rem; }
.live-dot { width: 6px; aspect-ratio: 1; border-radius: 50%; background: var(--green); box-shadow: 0 0 12px rgba(138,216,180,.55); }
.timestamp { margin-left: 14px; color: var(--muted); }

main { width: min(1600px, 94vw); margin: 0 auto; }

.hero {
  position: relative;
  display: grid;
  grid-template-columns: 1.15fr .85fr;
  min-height: 560px;
  align-items: center;
  overflow: hidden;
  border-bottom: 1px solid var(--line);
}

.hero-copy { position: relative; z-index: 2; max-width: 780px; padding: 115px 0 105px; }
.eyebrow { margin: 0 0 17px; color: #a8aca9; font-size: 0.58rem; font-weight: 500; letter-spacing: 0.32em; text-transform: uppercase; }
.hero h1 { margin: 0; font-size: clamp(3.5rem, 7.4vw, 7.6rem); font-weight: 200; line-height: 0.88; letter-spacing: -0.065em; }
.hero h1 em { color: #8a8e8b; font-style: normal; font-weight: 200; }
.hero-copy > p:last-child { max-width: 540px; margin: 34px 0 0; color: #858a87; font-size: .95rem; font-weight: 300; line-height: 1.9; }

.hero-web { position: absolute; inset: 0; opacity: 0.2; pointer-events: none; }
.hero-web::before, .hero-web::after, .hero-web span {
  content: ''; position: absolute; left: 74%; top: 46%; width: 900px; height: 1px; transform-origin: left center; background: linear-gradient(90deg, rgba(255,255,255,.42), transparent 60%);
}
.hero-web::after { transform: rotate(38deg); }
.hero-web span:nth-child(1) { transform: rotate(-38deg); }
.hero-web span:nth-child(2) { transform: rotate(70deg); }
.hero-web span:nth-child(3) { transform: rotate(-72deg); }

.web-emblem { position: relative; z-index: 2; display: grid; width: min(31vw, 355px); justify-self: center; justify-items: center; gap: 18px; }
.web-emblem svg { width: 100%; overflow: visible; filter: drop-shadow(0 0 20px rgba(255,255,255,.035)); }
.web-lines { stroke: rgba(242,241,237,.83); stroke-width: 1.15; stroke-linecap: round; stroke-linejoin: round; }
.web-node { fill: #f2f1ed; filter: drop-shadow(0 0 8px rgba(255,255,255,.45)); }
.web-emblem > span { color: #686d6a; font-size: .5rem; letter-spacing: .42em; text-transform: uppercase; }

.summary-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1px; padding: 24px 0; background: var(--line); }
.summary-grid article { position: relative; display: grid; min-height: 138px; padding: 25px; overflow: hidden; border: 0; background: #070908; }
.summary-grid article::after { content: ''; position: absolute; top: 0; left: 0; width: 100%; height: 1px; background: rgba(255,255,255,.32); }
.summary-grid span { color: #777c79; font-size: .59rem; font-weight: 500; letter-spacing: .22em; text-transform: uppercase; }
.summary-grid strong { align-self: end; font-size: 2.35rem; font-weight: 200; letter-spacing: -.05em; }
.summary-grid small { color: var(--muted); }
.summary-grid .alert-metric::after { background: var(--red); box-shadow: 0 0 18px rgba(255,75,85,.4); }
.summary-grid .alert-metric strong { color: var(--red); }

.dashboard-grid { display: grid; grid-template-columns: minmax(0, 1.45fr) minmax(360px, .65fr); gap: 14px; padding: 18px 0 90px; align-items: start; }
.primary-column, .insight-column { display: grid; gap: 14px; }
.insight-column { position: sticky; top: 94px; }

.panel { position: relative; overflow: hidden; border: 1px solid var(--line); border-radius: 0; background: rgba(7,9,8,.95); box-shadow: 0 28px 70px rgba(0,0,0,.18); }
.panel::before, .panel::after { content: ''; position: absolute; z-index: 2; width: 18px; height: 18px; pointer-events: none; }
.panel::before { top: -1px; left: -1px; border-top: 1px solid rgba(255,255,255,.6); border-left: 1px solid rgba(255,255,255,.6); }
.panel::after { right: -1px; bottom: -1px; border-right: 1px solid rgba(255,255,255,.32); border-bottom: 1px solid rgba(255,255,255,.32); }

.section-heading { display: flex; align-items: center; justify-content: space-between; gap: 18px; padding: 25px 26px; border-bottom: 1px solid var(--line); }
.section-heading h2 { margin: 0; font-size: 1.05rem; font-weight: 300; letter-spacing: .03em; }
.section-heading .eyebrow { margin-bottom: 7px; }
.count-badge { min-width: 32px; padding: 6px 9px; text-align: center; border: 1px solid rgba(255,255,255,.2); border-radius: 999px; color: #c7cac8; background: rgba(255,255,255,.025); font-size: .65rem; }
.danger-count { color: #ff7a98; border-color: rgba(255,49,95,.35); background: rgba(255,49,95,.08); }

.runner-grid { display: grid; grid-template-columns: repeat(2, minmax(0,1fr)); gap: 10px; padding: 18px; }
.runner-card { position: relative; padding: 19px; border: 1px solid rgba(255,255,255,.105); background: #090b0a; transition: border-color .2s, transform .2s, background .2s; }
.runner-card:hover { transform: translateY(-2px); border-color: color-mix(in srgb, var(--runner-accent) 55%, transparent); }
.runner-card::before { content: ''; position: absolute; inset: 0 auto 0 0; width: 1px; background: var(--runner-accent); }
.runner-identity { display: grid; grid-template-columns: auto 1fr auto; gap: 12px; align-items: center; }
.runner-avatar { display: grid; width: 40px; aspect-ratio: 1; place-items: center; border: 1px solid color-mix(in srgb, var(--runner-accent) 52%, transparent); border-radius: 50%; color: var(--runner-accent); background: transparent; font-family: 'Cascadia Code', Consolas, monospace; font-size: .65rem; font-weight: 500; }
.runner-card h3 { margin: 0 0 3px; font-size: .95rem; font-weight: 400; }
.runner-card p { margin: 0; color: var(--muted); font-size: .75rem; }
.runner-role { padding: 15px 0; }
.runner-meta { display: flex; gap: 8px; justify-content: space-between; padding-top: 12px; border-top: 1px solid var(--line); color: #9cb0ce; font-size: .65rem; }
.runner-meta span:last-child { max-width: 65%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; text-align: right; }

.status-pill { display: inline-flex; width: max-content; align-items: center; gap: 5px; padding: 5px 8px; border: 1px solid; border-radius: 999px; font-size: .56rem; letter-spacing: .08em; text-transform: uppercase; }
.status-pill::before { content: ''; width: 5px; aspect-ratio: 1; border-radius: 50%; background: currentColor; box-shadow: 0 0 8px currentColor; }
.status-active, .status-online, .status-clear { color: var(--green); border-color: rgba(33,217,162,.26); background: rgba(33,217,162,.08); }
.status-idle, .status-queued, .status-review, .status-degraded { color: var(--yellow); border-color: rgba(255,195,74,.26); background: rgba(255,195,74,.08); }
.status-offline { color: #8998ad; border-color: rgba(137,152,173,.26); background: rgba(137,152,173,.08); }
.status-blocked, .status-block { color: #ff6b8c; border-color: rgba(255,49,95,.34); background: rgba(255,49,95,.1); }
.status-complete { color: var(--blue-bright); border-color: rgba(64,157,255,.28); background: rgba(64,157,255,.08); }

.mission-list { display: grid; }
.mission-card { padding: 26px; border-bottom: 1px solid var(--line); }
.mission-card:last-child { border-bottom: 0; }
.mission-copy { display: flex; align-items: flex-start; justify-content: space-between; gap: 20px; }
.mission-copy h3 { margin: 7px 0 7px; font-size: 1rem; font-weight: 400; }
.mission-copy p { margin: 0; color: var(--muted); font-size: .76rem; line-height: 1.55; }
.mission-copy .mission-owner { color: #8da2c2; font-family: 'Cascadia Code', Consolas, monospace; font-size: .59rem; letter-spacing: .08em; text-transform: uppercase; }
.pathway { display: grid; grid-template-columns: repeat(4,1fr); margin: 28px 0 22px; padding: 0; list-style: none; }
.pathway li { position: relative; display: grid; justify-items: center; gap: 7px; color: #54657e; font-size: .62rem; }
.pathway li:not(:last-child)::after { content: ''; position: absolute; z-index: 0; top: 11px; left: calc(50% + 14px); right: calc(-50% + 14px); height: 1px; background: #292d2b; }
.path-dot { position: relative; z-index: 1; display: grid; width: 24px; aspect-ratio: 1; place-items: center; border: 1px solid #444946; border-radius: 50%; background: #090b0a; color: #737875; font-family: 'Cascadia Code', Consolas, monospace; font-size: .6rem; }
.pathway .reached, .pathway .current { color: #c5d7ef; }
.pathway .reached .path-dot, .pathway .current .path-dot { border-color: #e4e4df; color: #060807; background: #e4e4df; box-shadow: 0 0 16px rgba(255,255,255,.12); }
.mission-blocked .pathway .current .path-dot { border-color: var(--red); background: #ca1f4d; box-shadow: 0 0 16px rgba(255,49,95,.45); }
.mission-complete .pathway .reached .path-dot { border-color: var(--green); background: #0b8066; box-shadow: 0 0 16px rgba(33,217,162,.28); }
.mission-targets { display: flex; align-items: center; justify-content: space-between; gap: 16px; color: var(--muted); font-size: .62rem; }
.target-chips, .review-targets { display: flex; flex-wrap: wrap; gap: 6px; }
.target-chips { justify-content: flex-end; }
.target-chips code, .review-targets code { padding: 5px 7px; border: 1px solid rgba(255,255,255,.1); border-radius: 0; color: #aeb3b0; background: rgba(255,255,255,.025); font-size: .58rem; }

.risk-list { display: grid; gap: 9px; padding: 14px; }
.risk-card { display: grid; gap: 9px; width: 100%; padding: 16px; text-align: left; border: 1px solid var(--line); border-radius: 0; background: #090b0a; cursor: pointer; transition: border-color .2s, background .2s; }
.risk-card:hover, .risk-card:focus-visible { border-color: var(--line-bright); outline: none; }
.risk-card.selected { background: rgba(255,255,255,.035); }
.risk-block.selected { border-color: rgba(255,49,95,.55); box-shadow: inset 3px 0 var(--red); }
.risk-review.selected { border-color: rgba(255,195,74,.42); box-shadow: inset 3px 0 var(--yellow); }
.risk-clear.selected { border-color: rgba(33,217,162,.38); box-shadow: inset 3px 0 var(--green); }
.risk-card-top { display: flex; align-items: center; justify-content: space-between; color: var(--muted); font-family: 'Cascadia Code', Consolas, monospace; font-size: .56rem; text-transform: uppercase; }
.risk-card strong { font-size: .78rem; }
.risk-card > span:last-child { color: #8494ad; font-size: .68rem; line-height: 1.5; }

.evidence-heading { align-items: flex-start; }
.evidence-class { margin: 0 18px 12px; padding: 7px 9px; border-left: 2px solid currentColor; background: rgba(255,255,255,.025); color: var(--green); font-family: 'Cascadia Code', Consolas, monospace; font-size: .58rem; text-transform: uppercase; }
.evidence-class.evidence-heuristic { color: var(--yellow); }
.evidence-class.evidence-incomplete { color: var(--red); }
.evidence-path { position: relative; display: grid; gap: 0; margin: 0; padding: 20px 18px 10px; list-style: none; }
.evidence-path li { position: relative; display: grid; justify-items: center; }
.evidence-node { z-index: 1; display: grid; gap: 5px; width: 100%; padding: 14px; border: 1px solid rgba(255,255,255,.14); background: #090b0a; }
.evidence-node strong { font-size: .76rem; }
.evidence-node code { overflow-wrap: anywhere; color: #87a9d4; font-size: .61rem; }
.node-kind { width: max-content; color: var(--blue-bright); font-family: 'Cascadia Code', Consolas, monospace; font-size: .52rem; letter-spacing: .12em; text-transform: uppercase; }
.node-test { color: var(--violet); }
.relation-chip { display: flex; position: relative; z-index: 2; align-items: center; justify-content: space-between; gap: 15px; width: calc(100% - 28px); margin: 7px 0; padding: 6px 9px; border-left: 1px solid var(--red); border-right: 1px solid rgba(255,255,255,.35); color: #a8adaa; background: #111412; font-family: 'Cascadia Code', Consolas, monospace; font-size: .52rem; }
.recommendation { margin: 10px 18px; padding: 15px; border: 1px solid rgba(255,49,95,.2); background: linear-gradient(90deg, rgba(255,49,95,.09), rgba(64,157,255,.04)); }
.recommendation strong { font-size: .74rem; line-height: 1.55; }
.review-targets { padding: 10px 18px 20px; }
.review-targets .eyebrow { width: 100%; margin-bottom: 4px; }
.verification-path { border-top: 1px solid rgba(255,255,255,.06); }
.verification-path span { color: #c8cdca; font-size: .64rem; line-height: 1.5; }
.clear-evidence { display: flex; gap: 12px; margin: 18px; padding: 16px; border: 1px solid rgba(33,217,162,.22); background: rgba(33,217,162,.05); }
.clear-evidence > span { display: grid; flex: 0 0 30px; height: 30px; place-items: center; border-radius: 50%; color: var(--green); background: rgba(33,217,162,.12); }
.clear-evidence strong { font-size: .76rem; }
.clear-evidence p { margin: 5px 0 0; color: var(--muted); font-size: .66rem; line-height: 1.5; }

.provider-list, .activity-list { display: grid; margin: 0; padding: 4px 18px 14px; list-style: none; }
.provider-list li { display: grid; grid-template-columns: auto 1fr auto; gap: 11px; align-items: center; padding: 13px 3px; border-bottom: 1px solid var(--line); }
.provider-list li:last-child { border-bottom: 0; }
.provider-pulse { width: 6px; aspect-ratio: 1; border-radius: 50%; background: var(--blue); box-shadow: 0 0 9px var(--blue); }
.provider-list strong, .provider-list span { display: block; }
.provider-list strong { margin-bottom: 3px; font-size: .7rem; }
.provider-list div > span { color: var(--muted); font-size: .6rem; }
.provider-status { display: grid; justify-items: end; gap: 5px; }
.provider-status small { color: #63748d; font-size: .52rem; }

.git-summary { display: flex; gap: 13px; padding: 14px 20px; color: #899bb5; font-family: 'Cascadia Code', Consolas, monospace; font-size: .58rem; border-bottom: 1px solid var(--line); }
.git-summary strong { color: var(--blue-bright); font-weight: 500; }
.section-heading > code { color: var(--blue-bright); font-size: .65rem; }
.activity-list li { position: relative; display: grid; grid-template-columns: auto 1fr; gap: 11px; padding: 12px 2px; }
.activity-list li:not(:last-child)::before { content: ''; position: absolute; top: 27px; bottom: -3px; left: 3px; width: 1px; background: var(--line); }
.timeline-dot { z-index: 1; width: 7px; aspect-ratio: 1; margin-top: 4px; border-radius: 50%; background: var(--violet); box-shadow: 0 0 8px var(--violet); }
.activity-list strong, .activity-list span { display: block; }
.activity-list strong { margin-bottom: 4px; font-size: .68rem; }
.activity-list span { color: var(--muted); font-size: .56rem; }
.activity-list code { color: #95b9e8; }

.graph-completeness { font-family: 'Cascadia Code', Consolas, monospace; font-size: .58rem; text-transform: uppercase; }
.graph-completeness.complete { color: var(--green); }
.graph-completeness.partial { color: var(--yellow); }
.metric-grid { display: grid; grid-template-columns: repeat(3,1fr); gap: 8px; padding: 16px 18px 20px; }
.metric-grid div { display: grid; gap: 4px; justify-items: center; padding: 13px 5px; border: 1px solid var(--line); background: rgba(255,255,255,.02); }
.metric-grid strong { font-size: 1rem; }
.metric-grid span { color: var(--muted); font-size: .53rem; text-transform: uppercase; }
.graph-warning { margin: 0 18px 18px; color: var(--yellow); font-size: .65rem; }

.empty-state { display: grid; justify-items: center; padding: 54px 24px; text-align: center; }
.compact-empty { padding: 38px 24px; }
.empty-state h2, .empty-state h3 { margin: 11px 0 5px; }
.empty-state h3 { font-size: .9rem; }
.empty-state p, .muted-copy { margin: 0; color: var(--muted); font-size: .7rem; line-height: 1.6; }
.empty-glyph { display: grid; width: 42px; aspect-ratio: 1; place-items: center; border: 1px solid var(--line-bright); border-radius: 50%; color: var(--blue-bright); }
.clear-glyph { color: var(--green); border-color: rgba(33,217,162,.45); }
.radar-empty { width: 76px; aspect-ratio: 1; border: 1px solid rgba(64,157,255,.4); border-radius: 50%; background: repeating-radial-gradient(circle, transparent 0 11px, rgba(64,157,255,.1) 12px 13px); }

.state-shell { display: grid; min-height: 100vh; place-content: center; justify-items: center; padding: 30px; text-align: center; background: radial-gradient(circle, rgba(255,255,255,.055), transparent 27rem), var(--bg); }
.state-shell h1 { max-width: 700px; margin: 4px 0 13px; font-size: clamp(2rem,5vw,4.5rem); letter-spacing: -.06em; }
.state-shell > p:not(.eyebrow) { max-width: 550px; color: var(--muted); line-height: 1.6; }
.loading-radar { position: relative; width: 110px; aspect-ratio: 1; margin-bottom: 25px; overflow: hidden; border: 1px solid var(--line-bright); border-radius: 50%; background: repeating-radial-gradient(circle, transparent 0 17px, rgba(64,157,255,.12) 18px 19px); }
.loading-radar::before { content: ''; position: absolute; inset: 50% 50% auto 50%; width: 50%; height: 1px; transform-origin: left; background: var(--blue-bright); animation: spin 1.7s linear infinite; }
.loading-radar span { position: absolute; width: 7px; aspect-ratio: 1; top: 27%; right: 23%; border-radius: 50%; background: var(--red); box-shadow: 0 0 14px var(--red); }
.error-signal { display: grid; width: 70px; aspect-ratio: 1; place-items: center; margin-bottom: 25px; border: 1px solid rgba(255,49,95,.5); border-radius: 50%; color: var(--red); background: rgba(255,49,95,.08); box-shadow: 0 0 40px rgba(255,49,95,.15); font-size: 1.7rem; font-weight: 800; }
