.mission-complete .pathway .reached .path-dot { border-color: var(--green); background: #0b8066; box-shadow: 0 0 16px rgba(33,217,162,.28); }
.mission-targets { display: flex; align-items: center; justify-content: space-between; gap: 16px; color: var(--muted); font-size: .62rem; }
.target-chips, .review-targets { display: flex; flex-wrap: wrap; gap: 6px; }
.target-chips { justify-content: flex-end; }
.target-chips code, .review-targets code { padding: 5px 7px; border: 1px solid rgba(255,255,255,.1); border-radius: 0; color: #aeb3b0; background: rgba(255,255,255,.025); font-size: .58rem; }

.risk-list { display: grid; gap: 9px; padding: 14px; }
