.risk-card:hover, .risk-card:focus-visible { border-color: var(--line-bright); outline: none; }
.risk-card.selected { background: rgba(255,255,255,.035); }
.risk-block.selected { border-color: rgba(255,49,95,.55); box-shadow: inset 3px 0 var(--red); }
.risk-review.selected { border-color: rgba(255,195,74,.42); box-shadow: inset 3px 0 var(--yellow); }
.risk-clear.selected { border-color: rgba(33,217,162,.38); box-shadow: inset 3px 0 var(--green); }
.risk-card-top { display: flex; align-items: center; justify-content: space-between; color: var(--muted); font-family: 'Cascadia Code', Consolas, monospace; font-size: .56rem; text-transform: uppercase; }
.risk-card strong { font-size: .78rem; }
.risk-card > span:last-child { color: #8494ad; font-size: .68rem; line-height: 1.5; }

.evidence-heading { align-items: flex-start; }
.evidence-class { margin: 0 18px 12px; padding: 7px 9px; border-left: 2px solid currentColor; background: rgba(255,255,255,.025); color: var(--green); font-family: 'Cascadia Code', Consolas, monospace; font-size: .58rem; text-transform: uppercase; }
.evidence-class.evidence-heuristic { color: var(--yellow); }
