export type RunnerStatus = 'active' | 'idle' | 'offline';
export type EvidenceClass = 'confirmed' | 'heuristic' | 'incomplete';

export interface Team {
  id: string;
  name: string;
  callSign: string;
  objective: string;
}

export interface Runner {
  id: string;
  displayName: string;
  role: string;
  archetype: string;
  accent: string;
  initials: string;
  status: RunnerStatus;
  provider: string;
  currentMissionId?: string;
}

export interface Mission {
  id: string;
  title: string;
  intent: string;
  ownerId?: string;
  status: MissionStatus;
  targetCount: number;
  updatedAt: string;
  targets: string[];
}

export interface EvidenceNode {
  id: string;
  label: string;
  kind: 'file' | 'symbol' | 'test';
  location: string;
}

export interface EvidenceRelation {
  id: string;
  from: string;
  to: string;
  type: string;
  confidence: number;
  resolution: 'resolved' | 'heuristic' | 'partial';
