import { useState } from 'react';
import type { CoordinatePlan, PublicSession } from '../api';
import type { BrowserTeamSession, ConnectedAgent, PresenceInput } from '../network';
import type { DashboardSnapshot } from '../domain';
import { ConnectionHub } from './ConnectionHub';
import { Dashboard } from './Dashboard';

type View = 'connect' | 'plan' | 'tracker' | 'activity';

interface WorkflowProps {
  snapshot: DashboardSnapshot;
  plan: CoordinatePlan;
  sessions: PublicSession[];
  browserSession?: BrowserTeamSession;
  liveAgents: ConnectedAgent[];
  connectionBusy: boolean;
  connectionError?: string;
  presence: PresenceInput;
  onCreateTeam: (input: { teamName: string; objective: string; name: string; role: string }) => Promise<void>;
  onJoinTeam: (input: { teamId: string; inviteCode: string; name: string; role: string }) => Promise<void>;
  onPresence: (presence: PresenceInput) => Promise<void>;
  onLeaveTeam: () => void;
  onSave: (plan: CoordinatePlan) => Promise<void>;
}

export function Workflow({ snapshot, plan, sessions, browserSession, liveAgents, connectionBusy, connectionError, presence, onCreateTeam, onJoinTeam, onPresence, onLeaveTeam, onSave }: WorkflowProps) {
  const [view, setView] = useState<View>('connect');
  const [draft, setDraft] = useState(plan);
  const [saving, setSaving] = useState(false);
  const save = async () => { setSaving(true); try { await onSave(draft); } finally { setSaving(false); } };
  const addMission = () => setDraft({ ...draft, missions: [...draft.missions, { id: `mission-${crypto.randomUUID()}`, title: 'New task', owner: draft.team.members[0]?.id ?? '', status: 'queued', targets: [{ file: 'README.md' }] }] });

  return <div className="workflow-shell">
    <nav className="workflow-nav" aria-label="Product workflow">
      {(['connect', 'plan', 'tracker', 'activity'] as View[]).map((item) => <button className={view === item ? 'active' : ''} onClick={() => setView(item)} key={item}>{item === 'connect' ? '1. Connect team' : item === 'plan' ? '2. Plan & assign' : item === 'tracker' ? '3. Graph space' : 'Live activity'}</button>)}
    </nav>
    {view === 'tracker' ? <Dashboard snapshot={snapshot} /> : null}
    {view === 'connect' ? <ConnectionHub session={browserSession} agents={liveAgents} missions={snapshot.missions} presence={presence} error={connectionError} busy={connectionBusy} onCreate={onCreateTeam} onJoin={onJoinTeam} onPresence={onPresence} onLeave={onLeaveTeam} /> : null}
    {view === 'plan' ? <main className="focused-page"><header><p className="eyebrow">Step two</p><h1>Plan and assign</h1><p>The leader assigns tasks and declares the files or symbols each task expects to change.</p></header><div className="editor-list">{draft.missions.map((mission, index) => <article key={mission.id}><input aria-label="Task title" value={mission.title} onChange={(event) => { const missions = [...draft.missions]; missions[index] = { ...mission, title: event.target.value }; setDraft({ ...draft, missions }); }} /><select aria-label={`Owner for ${mission.title}`} value={mission.owner} onChange={(event) => { const missions = [...draft.missions]; missions[index] = { ...mission, owner: event.target.value }; setDraft({ ...draft, missions }); }}>{draft.team.members.map((member) => <option value={member.id} key={member.id}>{member.name}</option>)}</select><input aria-label="Target file" value={mission.targets[0]?.file ?? ''} onChange={(event) => { const missions = [...draft.missions]; missions[index] = { ...mission, targets: [{ ...mission.targets[0], file: event.target.value }] }; setDraft({ ...draft, missions }); }} /></article>)}</div><div className="editor-actions"><button disabled={!draft.team.members.length} onClick={addMission}>Add task</button><button className="primary-action" disabled={saving} onClick={save}>Save plan</button></div></main> : null}
    {view === 'activity' ? <main className="focused-page"><header><p className="eyebrow">Bounded activity telemetry</p><h1>Live presence.</h1><p>Browser presence and local Entire sessions stay explicitly distinct. Missing local metadata is shown as unavailable, never guessed.</p></header><div className="editor-list activity-editor">{liveAgents.map((agent) => <article key={agent.id}><strong>{agent.name}</strong><span>{agent.online ? 'Online' : 'Offline'} · {agent.role || 'Member'}</span><code>{agent.agent} · {agent.provider}</code><small>{agent.mission_id || 'No mission'} · {agent.last_heartbeat}</small></article>)}{sessions.map((session) => <article key={session.session_id}><strong>{session.agent}</strong><span>{session.status}</span><code>{session.session_id}</code><small>{session.worktree}</small></article>)}</div></main> : null}
  </div>;
}
import { useCallback, useEffect, useMemo, useState } from 'react';
import { loadDashboard, loadPlan, loadSessions, savePlan, type CoordinatePlan, type PublicSession } from './api';
import { Dashboard } from './components/Dashboard';
import { Workflow } from './components/Workflow';
import { createBrowserTeam, joinBrowserTeam, leaveBrowserTeam, loadTeamAgents, restoreBrowserTeam, sendBrowserHeartbeat, watchTeamEvents, type BrowserTeamSession, type ConnectedAgent, type PresenceInput } from './network';
import type { DashboardSnapshot } from './domain';

export default function App() {
  const [snapshot, setSnapshot] = useState<DashboardSnapshot>();
  const [error, setError] = useState<string>();
  const [plan, setPlan] = useState<CoordinatePlan>();
  const [sessions, setSessions] = useState<PublicSession[]>([]);
  const [browserSession, setBrowserSession] = useState<BrowserTeamSession | undefined>(() => restoreBrowserTeam());
  const [liveAgents, setLiveAgents] = useState<ConnectedAgent[]>([]);
  const [connectionBusy, setConnectionBusy] = useState(false);
  const [connectionError, setConnectionError] = useState<string>();
  const [presence, setPresence] = useState<PresenceInput>({});
  useEffect(() => {
    const controller = new AbortController();
    Promise.all([loadDashboard(controller.signal), loadPlan(controller.signal), loadSessions(controller.signal)]).then(([nextSnapshot, nextPlan, activity]) => { setSnapshot(nextSnapshot); setPlan(nextPlan); setSessions(activity.sessions); }).catch((reason: unknown) => {
      if (!controller.signal.aborted) setError(reason instanceof Error ? reason.message : 'Unable to load mission data');
    });
    return () => controller.abort();
  }, []);

  const refreshAgents = useCallback(async (active: BrowserTeamSession, signal?: AbortSignal) => {
    setLiveAgents(await loadTeamAgents(active, signal));
  }, []);

  useEffect(() => {
    if (!browserSession) return;
    const controller = new AbortController();
    const pulse = async () => {
      try {
        await sendBrowserHeartbeat(browserSession, presence);
        await refreshAgents(browserSession, controller.signal);
        setConnectionError(undefined);
      } catch (reason) {
        if (!controller.signal.aborted) setConnectionError(reason instanceof Error ? reason.message : 'Presence update failed');
      }
    };
    void pulse();
    const interval = window.setInterval(pulse, 15_000);
    void watchTeamEvents(browserSession, controller.signal, () => void refreshAgents(browserSession, controller.signal)).catch((reason: unknown) => {
      if (!controller.signal.aborted) setConnectionError(reason instanceof Error ? reason.message : 'Live team stream disconnected');
    });
    return () => { controller.abort(); window.clearInterval(interval); };
  }, [browserSession, presence, refreshAgents]);

  const runConnection = async (action: () => Promise<BrowserTeamSession>) => {
    setConnectionBusy(true); setConnectionError(undefined);
    try {
      const connected = await action();
      setBrowserSession(connected);
      await sendBrowserHeartbeat(connected, presence);
      await refreshAgents(connected);
    } catch (reason) {
      setConnectionError(reason instanceof Error ? reason.message : 'Unable to connect team');
    } finally { setConnectionBusy(false); }
  };

  const connectedSnapshot = useMemo(() => {
    if (!snapshot || liveAgents.length === 0) return snapshot;
    const runners = snapshot.runners.map((runner) => {
      const agent = liveAgents.find((candidate) => candidate.name.toLowerCase() === runner.displayName.toLowerCase());
      return agent ? { ...runner, status: agent.online ? 'active' as const : 'offline' as const, provider: `${agent.agent} · ${agent.provider}`, currentMissionId: agent.mission_id || runner.currentMissionId } : runner;
    });
    for (const [index, agent] of liveAgents.entries()) {
      if (runners.some((runner) => runner.displayName.toLowerCase() === agent.name.toLowerCase())) continue;
      runners.push({
        id: agent.member_id, displayName: agent.name, role: agent.role || 'Team member', archetype: 'Browser presence',
        accent: ['#a9d6ff', '#f4be7c', '#c9b6ff', '#78e2ba'][index % 4], initials: agent.name.split(/\s+/).map((part) => part[0]).join('').slice(0, 2).toUpperCase(),
        status: agent.online ? 'active' : 'offline', provider: `${agent.agent} · ${agent.provider}`, currentMissionId: agent.mission_id,
      });
    }
    return { ...snapshot, runners };
  }, [snapshot, liveAgents]);

  if (!snapshot || !plan) return <Dashboard loading={!error} error={error} />;
  return <Workflow
    snapshot={connectedSnapshot ?? snapshot} plan={plan} sessions={sessions} browserSession={browserSession} liveAgents={liveAgents}
    connectionBusy={connectionBusy} connectionError={connectionError} presence={presence}
    onCreateTeam={(input) => runConnection(() => createBrowserTeam(input))}
    onJoinTeam={(input) => runConnection(() => joinBrowserTeam(input))}
    onPresence={async (next) => { setPresence(next); if (browserSession) { setConnectionBusy(true); setConnectionError(undefined); try { await sendBrowserHeartbeat(browserSession, next); await refreshAgents(browserSession); } catch (reason) { setConnectionError(reason instanceof Error ? reason.message : 'Presence update failed'); } finally { setConnectionBusy(false); } } }}
    onLeaveTeam={() => { leaveBrowserTeam(); setBrowserSession(undefined); setLiveAgents([]); setConnectionError(undefined); }}
    onSave={async (next) => { const saved = await savePlan(next); setPlan(saved); setSnapshot(await loadDashboard()); }}
  />;
}
