		if err != nil {
			writeNetworkError(out, err)
			return
		}
		writeAPIJSON(out, http.StatusCreated, joined)
	})
	mux.HandleFunc("POST /api/v1/agents/connect", func(out http.ResponseWriter, request *http.Request) {
